insert into public.products (id, category_id, name, slug, description, base_price, style, occasion, is_active) values (gen_random_uuid(), (select id from public.categories where slug='party'), 'Tiered Notched Short Sleeve Dress', 'tiered-notched-short-sleeve-dress', 'A relaxed tiered midi dress with a notched V-neck, perfect for weekend brunches or a comfortable travel day. Why you''ll reach for it The soft, textured fabric drapes beautifully, keeping you comfortable from morning coffee to an evening stroll. A relaxed, tiered silhouette offers freedom of movement without sacrificing a polished look. The notched V-neck and short sleeves provide a versatile design, easy to dress up or down for any casual occasion. Fabric & care Made from a soft cotton-viscose blend, this dress is machine washable on a gentle cycle and tumbles dry low. Fit & sizing This dress offers a relaxed, true-to-size fit with a midi length that hits mid-calf. If you prefer a more tailored look, consider sizing down. Size US Length Bust Waist Sleeve Length S 4 49.8 39 27.2 8.9 M 6/8 50.8 41.3 29.1 9.1 L 10/12 51.8 44.1 31.9 9.3 XL 14/16 52.8 47.2 34.6 9.4 2XL 18 53.7 50.4 37.4 9.6 Wear it with Pair it with white canvas sneakers and a large tote bag for a relaxed weekend look, or d', 49.99, 'casual', 'party', true) on conflict (slug) do nothing;
