insert into public.products (id, category_id, name, slug, description, base_price, style, occasion, is_active) values (gen_random_uuid(), (select id from public.categories where slug='party'), 'Smocked Tube Slit Tiered Denim Dress', 'smocked-tube-slit-tiered-denim-dress', 'Crafted from a comfortable denim blend, this smocked tube dress with a tiered skirt and side slit is perfect for sunny weekend outings. Why you''ll reach for it The soft cotton-poly denim blend keeps you comfortable and cool throughout the day. A smocked tube top offers a secure, comfortable fit, while the tiered skirt adds playful movement. Its versatile design makes it ideal for sunny outdoor events or relaxed gatherings with friends. Fabric & care Made from 65% cotton and 35% polyester. Machine wash cold and tumble dry low for easy care. Fit & sizing This dress runs true-to-size with a snug smocked bodice and no stretch in the skirt. If you are between sizes, consider sizing up for comfort. Size US Length Waist Bust Bust Stretch Amount S 2/4 42.5 22 22 39.4 M 6 42.9 23.6 23.6 40.9 L 8 43.3 26 26 43.3 XL 12 43.7 28.3 28.3 45.7 Wear it with Pair it with white canvas sneakers and a woven crossbody bag for a casual day out, or dress it up with espadrille wedges and a straw tote for an ev', 58.99, 'romantic', 'party', true) on conflict (slug) do nothing;
insert into public.products (id, category_id, name, slug, description, base_price, style, occasion, is_active) values (gen_random_uuid(), (select id from public.categories where slug='party'), 'Lace Sweetheart Neck Flare Sleeve Mini Dress', 'lace-sweetheart-neck-flare-sleeve-mini-dress', 'This lace mini dress, with its delicate sweetheart neckline and flowing flare sleeves, is your go-to for a sun-drenched afternoon gathering. Why you''ll reach for it Crafted from a soft lace blend of nylon and spandex, this fully lined mini dress offers comfortable wear. The sweetheart neckline and playful flare sleeves create a flattering silhouette for easy movement. Ideal for a relaxed weekend outing or a casual gathering, it pairs effortlessly with your favorite sandals. Fabric & care Made from 90% nylon and 10% spandex, this dress is fully lined. Hand wash or professionally dry clean to maintain its delicate lace. Fit & sizing This dress has no stretch and a fitted bodice; consider sizing up if you prefer a more relaxed fit or are between sizes. Size US Length Bust Sleeve Length Waist S 2/4 27.2 27.6 29.5 26 M 6 27.6 29.1 29.9 27.6 L 8 28 30.7 30.3 29.1 Wear it with Pair it with strappy flat sandals and a woven tote for a sunny brunch, or dress it up with block heels and delicate l', 47.99, 'romantic', 'party', true) on conflict (slug) do nothing;
insert into public.products (id, category_id, name, slug, description, base_price, style, occasion, is_active) values (gen_random_uuid(), (select id from public.categories where slug='party'), 'Backless Leopard Long Sleeve Mini Dress', 'backless-leopard-long-sleeve-mini-dress', 'This leopard print polyester mini dress, with its open back and tie detail, makes a bold statement for a night out or a festival weekend. Why you''ll reach for it The soft, slightly stretchy polyester fabric moves with you, ensuring comfort from sunset to late night. An open back with a delicate tie detail adds a playful touch to the classic long-sleeve mini silhouette. The vibrant leopard print makes it an easy choice for a concert, a party, or a confident weekend look. Fabric & care Made from 100% polyester, this dress offers a slight stretch for comfort. Machine wash cold and tumble dry low to keep it looking fresh. Fit & sizing This mini dress fits true to size with a comfortable, slightly stretchy drape. If you''re between sizes, consider sizing up for a more relaxed feel through the body. Size US Length Shoulder Bust Hip Sleeve Length S 2/4 32.7 15 33.1 34.6 23.2 M 6 33.1 15.4 34.6 37 23.6 L 8 33.5 15.7 36.2 39.4 24 XL 10 33.9 16.1 37.8 41.7 24.4 Wear it with Pair it with black ank', 29.99, 'bold', 'party', true) on conflict (slug) do nothing;
insert into public.products (id, category_id, name, slug, description, base_price, style, occasion, is_active) values (gen_random_uuid(), (select id from public.categories where slug='party'), 'Side Slit Contrast Sleeveless Midi Tank Dress', 'perfee-side-slit-contrast-sleeveless-midi-tank-dress', 'The highly stretchy polyester-elastane midi tank dress, with its contrast side slit, offers easy comfort for a weekend brunch or travel day. Why you''ll reach for it The highly stretchy polyester-elastane blend moves with you, ensuring comfort from morning errands to evening plans. A striking contrast trim along the side slit adds a modern edge without feeling overdone. The relaxed midi length and tank silhouette make it a versatile piece for casual outings or layering. Fabric & care Crafted from 95% polyester and 5% elastane, this dress is easy to care for; machine wash cold and tumble dry low. Fit & sizing This dress runs true to size with a comfortable, body-skimming drape. If you''re between sizes, consider sizing down for a closer fit or up for a more relaxed feel. Size US Length Bust Waist Waist Stretch Amount S 4 50.8 29.5 25.2 38.6 M 6/8 51.2 31.1 26.8 40.2 L 10/12 51.6 33.5 29.1 42.5 XL 14 52 35.8 31.5 44.9 Wear it with Pair it with white canvas sneakers and an oversized tote fo', 33.99, 'casual', 'party', true) on conflict (slug) do nothing;
insert into public.products (id, category_id, name, slug, description, base_price, style, occasion, is_active) values (gen_random_uuid(), (select id from public.categories where slug='office'), 'Crochet Backless Cover Up Dress', 'hyfve-crochet-backless-cover-up-dress', 'This openwork crochet backless cover-up dress brings a relaxed, airy feel perfect for a sun-soaked beach day or lounging by the pool. Why you''ll reach for it The openwork crochet design provides an airy, breathable feel, ideal for warm weather comfort. Crafted from 100% polyester with moderate stretch, it offers an easy, relaxed fit for all-day wear. Effortlessly transition from swim to lounge, making it your go-to for vacation packing. Fabric & care Made from 100% polyester, this cover-up is simple to care for. Machine wash it cold and tumble dry on low. Fit & sizing This cover-up offers a relaxed fit, designed to drape easily over swimwear. We suggest choosing your usual size for the intended effortless look. Wear it with Layer it over your favorite one-piece swimsuit with flat leather sandals and a wide-brimmed hat for a classic beach look. For a relaxed resort dinner, wear it over a simple slip dress with espadrille wedges and a woven clutch.', 52.99, null, 'office', true) on conflict (slug) do nothing;
insert into public.products (id, category_id, name, slug, description, base_price, style, occasion, is_active) values (gen_random_uuid(), (select id from public.categories where slug='vacation'), 'Tropical Printed Midi Summer Boho Dress', 'very-j-tropical-printed-midi-summer-boho-dress', 'Float into vacation mode with this 100% viscose tropical print midi dress, featuring playful ruffles and a flattering tied waist. Why you''ll reach for it Made from 100% viscose, this dress offers a light, breathable feel, perfect for warm weather. The midi length, ruffled hem, and tied waist create a relaxed, flattering silhouette that moves with you. Effortlessly transition from a beachside stroll to a casual dinner or a weekend brunch with friends. Fabric & care This dress is made from 100% viscose. Machine wash cold and tumble dry low for best care. Fit & sizing This lined midi dress has a slightly stretchy feel and is designed to fit true-to-size. The tied waist allows for an adjustable, comfortable fit. Wear it with Pair with simple flat sandals and a straw tote for a beach vacation, or dress it up with espadrille wedges and delicate gold jewelry for a patio dinner.', 51.99, 'casual', 'vacation', true) on conflict (slug) do nothing;
insert into public.products (id, category_id, name, slug, description, base_price, style, occasion, is_active) values (gen_random_uuid(), (select id from public.categories where slug='party'), 'Lace Detail Backless Mini Cami Dress', 'lace-detail-backless-mini-cami-dress', 'This slightly stretchy polyester-cotton blend mini cami dress, with its delicate lace detail and tied back, is your choice for a relaxed evening out. Why you''ll reach for it The breathable 65% polyester, 35% cotton blend offers a comfortable feel for all-day wear. A relaxed mini silhouette with delicate lace and a tied back provides a playful, airy fit. This versatile cami dress is ideal for warm-weather gatherings or a relaxed vacation evening. Fabric & care Made from 65% polyester and 35% cotton, this dress is easy to care for. Machine wash cold and tumble dry low. Fit & sizing This dress offers a relaxed fit and runs true to size. If you prefer a more tailored look, consider sizing down. Size US Length Bust S 2/4 26.4 15.4 M 6/8 26.8 16.1 L 10 27.2 17.7 Wear it with For a daytime look, pair with flat sandals and a canvas tote; transition to evening with strappy heels and a minimalist clutch.', 23.99, 'romantic', 'party', true) on conflict (slug) do nothing;
insert into public.products (id, category_id, name, slug, description, base_price, style, occasion, is_active) values (gen_random_uuid(), (select id from public.categories where slug='office'), 'Plaid Long Sleeve Sweater Dress', 'plaid-long-sleeve-sweater-dress', 'This soft knit plaid sweater dress, with its defining belted waist and cozy long sleeves, offers effortless style for your busiest days. Why you''ll reach for it Crafted from a comfortable, slightly stretchy polyester knit for all-day wear. The classic plaid pattern and defining belted waist create a polished silhouette. A versatile piece that transitions smoothly from your work week to relaxed weekend plans. Fabric & care Made from 100% polyester. Machine wash cold and tumble dry low for easy care. Fit & sizing This sweater dress offers a comfortable, true-to-size fit with a flattering self-tie belt to cinch the waist. Choose your usual size. Size Length Shoulder Bust Sleeve Length Hip One Size 26.8 16.1 40.9 22.4 0 Wear it with Pair with knee-high boots and a structured tote for an office-ready look, or dress down with ankle boots and a cross-body bag for a weekend outing.', 47.99, null, 'office', true) on conflict (slug) do nothing;
insert into public.products (id, category_id, name, slug, description, base_price, style, occasion, is_active) values (gen_random_uuid(), (select id from public.categories where slug='office'), 'Tie Front Plaid Long Sleeve Dress', 'tie-front-plaid-long-sleeve-dress', 'The relaxed silhouette of this plaid long sleeve dress, featuring a soft tie front, makes it ideal for a polished everyday look. Why you''ll reach for it Crafted from a 95% polyester, 5% spandex blend, it offers comfortable movement and a soft drape. The adjustable tie front cinches the waist, creating a flattering shape without sacrificing comfort. A versatile piece that transitions effortlessly from a productive workday to a relaxed weekend outing. Fabric & care Made from a 95% polyester, 5% spandex blend. Machine wash cold and tumble dry low for easy care. Fit & sizing This dress offers a relaxed fit that''s true to size. If you''re between sizes, consider sizing down for a slightly closer look. Size Length Waist Bust S 51.6 26.8 31.9 M 52 28.3 33.5 L 52.4 30.7 35.8 XL 52.8 33.1 38.2 Wear it with Layer it with a denim jacket and white sneakers for a casual coffee run, or pair with ankle boots and a structured tote for an afternoon meeting.', 54.99, 'romantic', 'office', true) on conflict (slug) do nothing;
